import {contents,sections,summaryRows} from './splay-proof-content.js';
import {localRound,operationOptions,parseKeys,runOperation} from './splay-proof-engine.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.abs(n)<0.0005?'0.000':n.toFixed(3);
const $=s=>document.querySelector(s);
const node=(label,left=null,right=null)=>({label,left,right});
const leaf=s=>node(s);
export function rotationTrees(kind){const A=leaf('A'),B=leaf('B'),C=leaf('C'),D=leaf('D');return kind==='zig'?[node('p',node('x',A,B),C),node('x',A,node('p',B,C))]:kind==='zigzig'?[node('g',node('p',node('x',A,B),C),D),node('x',A,node('p',B,node('g',C,D)))]:[node('g',node('p',A,node('x',B,C)),D),node('x',node('p',A,B),node('g',C,D))]}
export function treeSVG(root,{title='树结构',sizes={},focus=[],mirror=false,symbolic=false}={}){
 const points=[],links=[];let i=0,maxDepth=0;
 function walk(n,depth=0){if(!n)return null;const left=walk(n.left,depth+1),p={n,x:52+82*i++,y:52+90*depth};points.push(p);const right=walk(n.right,depth+1);if(left)links.push([p,left]);if(right)links.push([p,right]);maxDepth=Math.max(maxDepth,depth);return p}walk(root);
 const width=Math.max(330,104+82*Math.max(0,i-1)),height=Math.max(150,125+maxDepth*90);if(mirror)points.forEach(p=>p.x=width-p.x);
 return `<svg xmlns="http://www.w3.org/2000/svg" class="sp-tree" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}" role="img" aria-label="${esc(title)}"><title>${esc(title)}</title><desc>圆形表示节点；三角形表示内部保持不变的子树。s 为子树大小或权重和，r 为 log₂s。</desc><g font-family="Microsoft YaHei, sans-serif" text-anchor="middle">${links.map(([a,b])=>`<path d="M${a.x},${a.y} L${b.x},${b.y}" stroke="#9cafa3" stroke-width="2"/>`).join('')}${points.map(({n,x,y})=>{const label=n.label??n.key,triangle=symbolic&&/^[A-D]$/.test(label),s=symbolic?sizes[label]:n.size,active=label==='x'||focus.includes(n.key);return `<g data-sp-node="${esc(label)}" data-x="${x}" data-y="${y}" transform="translate(${x} ${y})">${triangle?'<path d="M0,-19 L-24,20 L24,20 Z" fill="#eaf0f7" stroke="#728bab"/>':`<circle r="22" fill="${active?'#235e4b':'#f5f8f1'}" stroke="${active?'#235e4b':'#7b9283'}" stroke-width="2"/>`}<text y="6" font-size="17" font-weight="600" fill="${active&&!triangle?'#ffffff':'#20332f'}">${esc(label)}</text>${s!==undefined?`<text y="39" font-size="12" fill="#4f6358">s=${Number.isInteger(s)?s:fmt(s)}</text>${!triangle?`<text y="55" font-size="11" fill="#68756f">r=${fmt(Math.log2(s))}</text>`:''}`:''}</g>`}).join('')}${!root?'<text x="165" y="80" fill="#697570" font-size="17">∅ 空树 · Φ = 0</text>':''}</g></svg>`;
}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
export function proofMarkdown(){const plain=s=>s.replace(/<a href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g,'[$2]($1)').replace(/<h3>(.*?)<\/h3>/g,'\n### $1\n').replace(/<div class="sp-equation">([\s\S]*?)<\/div>/g,'\n```text\n$1\n```\n').replace(/<li>/g,'\n- ').replace(/<\/(?:p|li|details)>/g,'\n\n').replace(/<[^>]+>/g,'').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&');return '# Splay Tree：操作与均摊证明\n\n在线交互图示：https://stan-haochen.github.io/ads-knowledge-site/#avl/splay-proof\n\n'+summaryRows.map(r=>'- '+r.join(' · ')).join('\n')+'\n\n'+contents.filter(([id])=>sections[id]).map(([id,title])=>'## '+title+'\n\n'+plain(sections[id])).join('\n\n')}
function stat(label,value){return `<div><small>${label}</small><strong>${value}</strong></div>`}
function forest(trees,focus,title){return `<div class="sp-forest">${trees.map((t,i)=>`<figure><figcaption>${title} · 分量 ${i+1}</figcaption><div class="sp-scroll">${treeSVG(t,{focus,title:title+'分量'+(i+1)})}</div></figure>`).join('')}</div>`}
export function mountSplayProof(){
 let index=0,trace,timer=null,kind='zigzig',mirror=false,actualSize=false,roundActual=false;
 document.title='Splay Tree：所有基本操作的均摊证明 · ADS';$('#breadcrumb').textContent='第一课 / Splay 完整证明';document.querySelectorAll('[data-chapter]').forEach(a=>a.classList.toggle('active',a.dataset.chapter==='avl'));
 const section=(id,extra='')=>`<section class="sp-section" id="sp-${id}"><div class="eyebrow">SPLAY / PROOF NOTE</div><h2>${contents.find(x=>x[0]===id)[1]}</h2>${extra}${sections[id]||''}</section>`;
 $('#main').innerHTML=`<article class="sp-page"><div class="eyebrow">CHAPTER 01 / ANALYSIS COMPANION</div><h1>Splay Tree<br><span class="sp-subtitle">从一次旋转，到所有基本操作的均摊证明</span></h1><p class="intro">先画清哪些子树改变，再精确结算势能。按“局部不等式 → 访问引理 → 森林组合 → 操作序列”完成整条证明链。</p><div class="sp-actions"><a href="#avl/splay-potential">连续访问动画 ↗</a><a href="#avl/splay-delete">删除指针细节 ↗</a><button id="sp-export">下载完整证明 Markdown</button></div><div class="sp-road"><b>不相交子树</b><span>→</span><b>三种旋转</b><span>→</span><b>访问引理</b><span>→</span><b>Split / Join</b><span>→</span><b>所有基本操作</b></div><p class="sp-caption">范围：标准有序集合接口，以及明确满足常数时间维护条件的增广；“所有”不包括任意自定义操作。</p><div class="sp-toc" aria-label="证明专题目录">${contents.map(([id,title])=>`<button data-sp-jump="${id}">${title}</button>`).join('')}</div><details class="sp-summary"><summary>展开操作复杂度总表（含条件）</summary><div class="sp-scroll"><table><thead><tr><th>操作</th><th>实现分解</th><th>开销</th><th>必要条件</th></tr></thead><tbody>${summaryRows.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>
 ${section('model')}
 ${section('rotation',`<div class="sp-interactive"><div class="sp-toolbar"><label>完整轮类型<select id="sp-round"><option value="zigzig">Zig-zig · 同向双旋</option><option value="zigzag">Zig-zag · 反向双旋</option><option value="zig">Zig · 最后一轮</option></select></label><button id="sp-mirror" aria-pressed="false">左右镜像</button><button id="sp-svg-export">下载当前旋转 SVG</button><button id="sp-round-size" aria-pressed="false">原始字号</button></div><p>改变子树总权重与节点权重，检查同一组符号推导。A–D 可以为 0；x、p、g 必须为正。默认均为 1。</p><div class="sp-weights">${['a','b','c','d','x','p','g'].map(k=>`<label data-sp-weight-label="${k}">${k<='d'?k.toUpperCase()+' 子树':'w('+k+')'}<input data-sp-weight="${k}" type="number" min="${k<='d'?0:1}" max="100" value="1" aria-label="${k} 权重"></label>`).join('')}</div><p role="alert" id="sp-weight-error"></p><p class="sp-caption">图和表可横向滚动；切换“原始字号”可逐个阅读节点标注。</p><div id="sp-round-visual"></div></div>`)}
 ${section('access')}
 ${section('operations',`<p>每个实验从输入指定的普通 BST 开始；输入顺序决定初始树形。逐步观察整棵树或森林，核对每步 c、ΔΦ、ĉ，以及跨步骤相消。c 列只计旋转；搜索与常数结构工作按第 1 节换算，区间输出另计。</p><div class="sp-interactive"><div class="sp-toolbar"><label class="sp-wide">操作<select id="sp-operation">${operationOptions.map(([id,title])=>`<option value="${id}" ${id==='delete'?'selected':''}>${title}</option>`).join('')}</select></label><label class="sp-wide">初始树（按顺序插入）<input id="sp-keys" value="50 30 70 20 40 60 80 35 45" aria-label="初始树"></label><label>键 / k<input id="sp-key" value="50" type="number"></label><label id="sp-high-wrap" hidden>区间右端 h<input id="sp-high" value="65" type="number"></label><label class="sp-wide" id="sp-right-wrap" hidden>Join 右树<input id="sp-right" value="100 90 110"></label><button id="sp-run" class="primary">生成操作</button><button id="sp-size" aria-pressed="false">原始字号</button></div><div class="sp-presets"><button data-sp-preset="chain">深链插入</button><button data-sp-preset="miss">失败查找</button><button data-sp-preset="delete">删除双孩子根</button><button data-sp-preset="range">区间隔离与恢复</button><button data-sp-preset="empty">空树边界</button></div><p role="alert" id="sp-op-error"></p><div class="sp-toolbar sp-player"><button id="sp-prev" aria-label="证明实验上一步">◀</button><button id="sp-play">▶ 播放</button><button id="sp-next" aria-label="证明实验下一步">▶|</button><input id="sp-seek" type="range" min="0" value="0" aria-label="证明实验步骤"><select id="sp-phase" aria-label="按阶段跳转"></select></div><div id="sp-operation-visual" aria-live="polite"></div><details><summary>展开所有步骤的势能账本</summary><div class="sp-scroll" id="sp-ledger"></div></details></div>`)}
 ${['search','split','join','insert','delete','augment','bulk','weighted','audit'].map(id=>section(id)).join('')}<div class="sp-actions"><button data-sp-jump="model">返回证明起点 ↑</button><a href="#mindmap/avl">课程地图 ↗</a></div></article>`;
 document.querySelectorAll('[data-sp-jump]').forEach(b=>b.onclick=()=>$('#sp-'+b.dataset.spJump).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));
 $('#sp-export').onclick=()=>download('ADS-Splay-amortized-proofs.md',proofMarkdown(),'text/markdown;charset=utf-8');
 function renderRound(){try{const w=Object.fromEntries([...document.querySelectorAll('[data-sp-weight]')].map(e=>[e.dataset.spWeight,Number(e.value)]));if(Object.values(w).some(v=>v>100))throw Error('演示权重最大为 100。');const r=localRound(kind,w),trees=rotationTrees(kind),subs={A:w.a,B:w.b,C:w.c,D:w.d};$('#sp-weight-error').textContent='';for(const k of ['d','g'])$(`[data-sp-weight-label="${k}"]`).hidden=kind==='zig';const diagrams=trees.map((t,i)=>treeSVG(t,{title:i?'整轮之后':'整轮之前',sizes:{...subs,...(i?r.after:r.before)},symbolic:true,mirror}));
 const sets=kind==='zigzig'?[r.before.x,r.after.g,'旧 subtree(x) = {x} ∪ A ∪ B','新 subtree(g) = {g} ∪ C ∪ D']:kind==='zigzag'?[r.after.p,r.after.g,'新 subtree(p) = {p} ∪ A ∪ B','新 subtree(g) = {g} ∪ C ∪ D']:null;
 $('#sp-round-visual').innerHTML=`<div class="sp-pair">${diagrams.map((s,i)=>`<figure><figcaption>${i?'整轮之后':'整轮之前'} <small>${kind==='zig'?'旋转 x':kind==='zigzig'?'先旋转 p，再旋转 x':'先旋转 x，再旋转 x'}</small></figcaption><div class="sp-scroll">${s}</div></figure>`).join('')}</div>${sets?`<div class="sp-disjoint"><b>新 x 的总权重 S = ${fmt(r.after.x)}</b><div class="sp-setbar"><span style="width:${100*sets[0]/r.after.x}%">${fmt(sets[0])}</span><span style="width:${100*sets[1]/r.after.x}%">${fmt(sets[1])}</span></div><p><span class="sp-dot">①</span> ${sets[2]}<br><span class="sp-dot blue">②</span> ${sets[3]}<br>两集合不相交；余下的浅色部分是 ${kind==='zigzig'?'p':'x'} 本身的权重。<br>log₂a + log₂b = ${fmt(Math.log2(sets[0])+Math.log2(sets[1]))} ≤ 2log₂S−2 = ${fmt(2*Math.log2(r.after.x)-2)}</p></div>`:'<p class="sp-disjoint">Zig 无需不相交子树不等式；新 x 的权重等于旧 p，且新 p 包含在新 x 中。</p>'}<div class="sp-stats">${stat('旋转 c',r.cost)}${stat('势能变化 ΔΦ',fmt(r.delta))}${stat('均摊 ĉ = c+ΔΦ',fmt(r.amortized))}${stat('3Δr(x) + Zig 常数',fmt(r.bound))}</div><p class="sp-check">✓ 数值检查：${fmt(r.amortized)} ≤ ${fmt(r.bound)}。完整普遍性证明见下文，有限案例不是证明。</p><div class="sp-scroll"><table><thead><tr><th>节点</th><th>s → s′</th><th>r → r′</th><th>Δr</th></tr></thead><tbody>${Object.keys(r.before).map(k=>`<tr><th>${k}</th><td>${fmt(r.before[k])} → ${fmt(r.after[k])}</td><td>${fmt(Math.log2(r.before[k]))} → ${fmt(Math.log2(r.after[k]))}</td><td>${fmt(Math.log2(r.after[k]/r.before[k]))}</td></tr>`).join('')}</tbody></table></div>`;
 $('#sp-svg-export').onclick=()=>{const bodies=diagrams.map(s=>s.replace('<svg ','<svg x="0" y="80" '));const widths=diagrams.map(s=>+s.match(/width="(\d+)"/)[1]),height=Math.max(...diagrams.map(s=>+s.match(/height="(\d+)"/)[1]))+120;download(`Splay-${kind}.svg`,`<svg xmlns="http://www.w3.org/2000/svg" width="${widths[0]+widths[1]+40}" height="${height}" viewBox="0 0 ${widths[0]+widths[1]+40} ${height}"><rect width="100%" height="100%" fill="#fafbf8"/><text x="24" y="32" font-size="21" font-family="sans-serif">${kind} · before / after · c+ΔΦ=${fmt(r.amortized)} ≤ ${fmt(r.bound)}</text>${bodies[0]}<g transform="translate(${widths[0]+40},0)">${bodies[1]}</g></svg>`,'image/svg+xml')};
 }catch(e){$('#sp-weight-error').textContent=e.message}}
 $('#sp-round-size').onclick=()=>{roundActual=!roundActual;$('#sp-round-visual').classList.toggle('sp-actual',roundActual);$('#sp-round-size').setAttribute('aria-pressed',String(roundActual));$('#sp-round-size').textContent=roundActual?'适应画布':'原始字号'};$('#sp-round').onchange=e=>{kind=e.target.value;renderRound()};$('#sp-mirror').onclick=()=>{mirror=!mirror;$('#sp-mirror').setAttribute('aria-pressed',String(mirror));renderRound()};document.querySelectorAll('[data-sp-weight]').forEach(e=>e.oninput=renderRound);renderRound();
 function stop(){clearInterval(timer);timer=null;if($('#sp-play'))$('#sp-play').textContent='▶ 播放'}
 function fields(){const type=$('#sp-operation').value;$('#sp-high-wrap').hidden=type!=='range';$('#sp-right-wrap').hidden=type!=='join'}
 function paint(){const f=trace.frames[index],p=trace.frames[Math.max(0,index-1)];$('#sp-prev').disabled=index===0;$('#sp-next').disabled=index===trace.frames.length-1;$('#sp-seek').value=index;$('#sp-phase').value=index;$('#sp-operation-visual').innerHTML=`<div class="sp-step"><small>STEP ${index+1} / ${trace.frames.length}</small><h3>${esc(f.phase)}</h3><p>${esc(f.msg)}</p></div><div class="sp-stats">${stat('本步旋转 c',f.c)}${stat('本步 ΔΦ',fmt(f.delta))}${stat('本步 ĉ',fmt(f.amortized))}${stat('当前森林 Φ',fmt(f.phi))}</div><div class="sp-pair sp-operation-pair ${actualSize?'sp-actual':''}"><div>${forest(p.trees,p.focus,index?'上一步':'初始')}</div><div>${forest(f.trees,f.focus,'当前')}</div></div><div class="sp-equation">累计旋转 ${f.rotations} = 累计均摊 ${fmt(f.rotations+f.phi-trace.initialPhi)} + Φ₀ ${fmt(trace.initialPhi)} − 当前 Φ ${fmt(f.phi)}</div><p class="sp-caption">绿色节点为当前涉及的节点。每个存活节点只属于一个森林分量；空树明确保留显示。结果：${esc(Array.isArray(trace.result)?'['+trace.result.join(', ')+']':trace.result??'不存在')}（完整操作的返回值）</p>`;document.querySelectorAll('[data-sp-ledger]').forEach(e=>e.classList.toggle('active',+e.dataset.spLedger===index));}
 function run(){stop();try{fields();trace=runOperation($('#sp-operation').value,parseKeys($('#sp-keys').value),Number($('#sp-key').value),parseKeys($('#sp-right').value),Number($('#sp-high').value));index=0;$('#sp-op-error').textContent='';$('#sp-seek').max=trace.frames.length-1;$('#sp-phase').innerHTML=trace.frames.map((f,i)=>`<option value="${i}">${i+1}. ${esc(f.phase)}</option>`).join('');$('#sp-ledger').innerHTML=`<table><thead><tr><th>阶段</th><th>c</th><th>Φ</th><th>ΔΦ</th><th>ĉ</th></tr></thead><tbody>${trace.frames.map((f,i)=>`<tr data-sp-ledger="${i}"><td><button data-sp-seek="${i}">${i+1}. ${esc(f.phase)}</button></td><td>${f.c}</td><td>${fmt(f.phi)}</td><td>${fmt(f.delta)}</td><td>${fmt(f.amortized)}</td></tr>`).join('')}</tbody></table>`;document.querySelectorAll('[data-sp-seek]').forEach(b=>b.onclick=()=>{stop();index=+b.dataset.spSeek;paint()});paint()}catch(e){$('#sp-op-error').textContent=e.message}}
 $('#sp-size').onclick=()=>{actualSize=!actualSize;$('#sp-size').setAttribute('aria-pressed',String(actualSize));$('#sp-size').textContent=actualSize?'适应画布':'原始字号';paint()};$('#sp-operation').onchange=run;$('#sp-run').onclick=run;$('#sp-prev').onclick=()=>{stop();index--;paint()};$('#sp-next').onclick=()=>{stop();index++;paint()};$('#sp-seek').oninput=e=>{stop();index=+e.target.value;paint()};$('#sp-phase').onchange=e=>{stop();index=+e.target.value;paint()};$('#sp-play').onclick=()=>{if(timer){stop();return}if(index===trace.frames.length-1)index=0;$('#sp-play').textContent='Ⅱ 暂停';timer=setInterval(()=>{index++;paint();if(index===trace.frames.length-1)stop()},1100)};
 const presets={chain:['insert','7 6 5 4 3 2 1',0,65],miss:['access','10 20 30 40 50',55,65],delete:['delete','50 30 70 20 40 60 80 35 45',50,65],range:['range','50 30 70 20 40 60 80 35 45',35,65],empty:['delete','',5,65]};document.querySelectorAll('[data-sp-preset]').forEach(b=>b.onclick=()=>{const [op,keys,k,h]=presets[b.dataset.spPreset];$('#sp-operation').value=op;$('#sp-keys').value=keys;$('#sp-key').value=k;$('#sp-high').value=h;run()});run();return stop;
}
